    rs = [r for r in range(h) if all(v == 8 for v in grid[r])]
    cs = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    r0, r1 = [0] + [r + 1 for r in rs], rs + [h]
    c0, c1 = [0] + [c + 1 for c in cs], cs + [w]
    nr, nc = len(r0), len(c0)

    points = {2: [], 3: []}
    for i in range(nr):
        for j in range(nc):
            for r in range(r0[i], r1[i]):
                for c in range(c0[j], c1[j]):
                    if grid[r][c] in points:
                        points[grid[r][c]].append((i, j))

    # A marker pair draws a straight segment between its cells.
    coverage = {2: set(), 3: set()}
    for color, pts in points.items():
        for i, j in pts:
            for ii, jj in pts:
                if i == ii:
                    coverage[color].update((i, k) for k in range(min(j, jj), max(j, jj) + 1))
                if j == jj:
                    coverage[color].update((k, j) for k in range(min(i, ii), max(i, ii) + 1))

    for i, j in coverage[2] | coverage[3]:
        color = 6 if (i, j) in coverage[2] and (i, j) in coverage[3] else (
            2 if (i, j) in coverage[2] else 3)
        for r in range(r0[i], r1[i]):
            for c in range(c0[j], c1[j]):
                out[r][c] = color
    return out
